const fs = require\("fs"\);
const { tables, varToTable } = require\("/tmp/erdgen.cjs"\);
const bySql = {}; tables.forEach\(t => bySql[t.sqlName] = t\);

const TRUE_GLOBAL = new Set\(["organizations","permissions","role_permissions","accounts","sessions","verification_tokens","users"]\);

function classify\(t\) {
  if \(t.hasOrgId\) return { kind: "tenant", note: "org_id" };
  if \(TRUE_GLOBAL.has\(t.sqlName\)\) return { kind: "global", note: "platform anchor" };
  // find first FK whose target is tenant or reaches tenant
  for \(const fk of t.fks\) {
    const p = bySql[fk.targetTable];
    if \(!p\) continue;
    if \(p.hasOrgId\) return { kind: "via-parent", note: `via ${fk.field} → ${fk.targetTable}` };
  }
  for \(const fk of t.fks\) {
    const p = bySql[fk.targetTable];
    if \(!p\) continue;
    if \(TRUE_GLOBAL.has\(p.sqlName\)\) return { kind: "via-parent", note: `via ${fk.field} → ${fk.targetTable}` };
    // 2-hop
    for \(const fk2 of p.fks\) {
      const gp = bySql[fk2.targetTable];
      if \(gp && gp.hasOrgId\) return { kind: "via-parent", note: `via ${fk.field} → ${fk.targetTable} → ${fk2.targetTable}` };
    }
  }
  return { kind: "unclear", note: "?" };
}

// group tables by source module file
const byFile = {};
for \(const t of tables\) { \(byFile[t.file] ||= []\).push\(t\); }

// counts
let nTenant=0, nGlobal=0, nVia=0, nUnclear=0;
for \(const t of tables\) { const c = classify\(t\).kind; if\(c==="tenant"\)nTenant++; else if\(c==="global"\)nGlobal++; else if\(c==="via-parent"\)nVia++; else nUnclear++; }

// onDelete distribution across all fks
const od = {}; tables.forEach\(t=>t.fks.forEach\(fk=>{od[fk.onDelete]=\(od[fk.onDelete]||0\)+1;}\)\);

const out = {
  counts: { total: tables.length, tenant: nTenant, global: nGlobal, viaParent: nVia, unclear: nUnclear },
  onDelete: od,
  byFile, classify: null,
  tables: tables.map\(t => \({ sql: t.sqlName, file: t.file, ...classify\(t\), fks: t.fks.map\(f=>\({field:f.field,target:f.targetTable,onDelete:f.onDelete,notNull:f.notNull}\)\) }\)\)
};
fs.writeFileSync\("/tmp/erddata.json", JSON.stringify\(out, null, 2\)\);
console.log\("counts:", JSON.stringify\(out.counts\)\);
console.log\("onDelete:", JSON.stringify\(out.onDelete\)\);
console.log\("modules:", Object.keys\(byFile\).length\);
